<script setup lang="ts">
import { reactive, ref, watch } from 'vue'; import { z } from 'zod'; import AppDrawer from '@/components/common/AppDrawer.vue'; import type { Store, StoreInput } from '@/types/domain'
const props = defineProps<{ open: boolean; store?: Store }>(); const emit = defineEmits<{ close: []; submit: [value: StoreInput] }>(); const submitting = ref(false); const errors = ref<Record<string, string>>({})
const empty: StoreInput = { name: '', city: '', manager: '', address: '', phone: '', target: 1000000, status: 'open' }; const form = reactive<StoreInput>({ ...empty })
const schema = z.object({ name: z.string().min(2, '至少输入 2 个字符'), city: z.string().min(2, '请输入城市'), manager: z.string().min(2, '请输入负责人'), address: z.string().min(5, '请输入详细地址'), phone: z.string().regex(/^[0-9-]{7,20}$/, '电话号码格式不正确'), target: z.coerce.number().positive('目标必须大于 0'), status: z.enum(['open', 'closed']) })
watch(() => [props.open, props.store] as const, ([open, store]) => { if (open) Object.assign(form, store ? { name: store.name, city: store.city, manager: store.manager, address: store.address, phone: store.phone, target: store.target, status: store.status } : empty); errors.value = {} })
async function submit() { if (submitting.value) return; const result = schema.safeParse(form); if (!result.success) { errors.value = Object.fromEntries(result.error.issues.map((x) => [String(x.path[0]), x.message])); return } submitting.value = true; emit('submit', result.data); setTimeout(() => { submitting.value = false }, 500) }
</script>
<template><AppDrawer :open="open" :title="store ? '编辑门店' : '新增门店'" @close="$emit('close')"><form class="drawer-form" @submit.prevent="submit"><label class="field"><span>门店名称</span><input v-model.trim="form.name" placeholder="例如：上海静安旗舰店"/><small v-if="errors.name">{{ errors.name }}</small></label><div class="form-columns"><label class="field"><span>城市</span><input v-model.trim="form.city"/></label><label class="field"><span>负责人</span><input v-model.trim="form.manager"/></label></div><label class="field"><span>详细地址</span><input v-model.trim="form.address"/></label><div class="form-columns"><label class="field"><span>联系电话</span><input v-model.trim="form.phone"/><small v-if="errors.phone">{{ errors.phone }}</small></label><label class="field"><span>月度目标</span><input v-model.number="form.target" type="number" min="1"/></label></div><label class="field"><span>营业状态</span><select v-model="form.status"><option value="open">营业中</option><option value="closed">已停业</option></select></label></form><template #footer><button class="btn-ghost" type="button" @click="$emit('close')">取消</button><button class="btn-primary" :disabled="submitting" @click="submit">{{ submitting ? '保存中…' : '保存门店' }}</button></template></AppDrawer></template>
